/* Demonstrates using shutdown() to close only the writing side of a socket (half-close). */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/socket.h>
#include <errno.h>
#include <string.h>

// Dummy function to simulate a connected socket for demonstration
int get_dummy_socket() {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd == -1) {
        perror("socket initialization failed");
        exit(EXIT_FAILURE);
    }
    // In a real app, connect() or accept() would be called here.
    return fd;
}

int main(void) {
    int sockfd = get_dummy_socket();
    int ret;
    const char *message = "Finished sending data.\n";

    printf("Socket descriptor obtained: %d\n", sockfd);

    // 1. Send final data
    if (send(sockfd, message, strlen(message), 0) == -1) {
        perror("send failed");
        goto cleanup;
    }
    printf("Data sent successfully.\n");

    // 2. Shut down the transmission side (SHUT_WR)
    // This sends a FIN packet, telling the peer we won't send more data.
    ret = shutdown(sockfd, SHUT_WR);

    if (ret == -1) {
        if (errno == ENOTCONN) {
            fprintf(stderr, "Socket was not connected, proceeding with close.\n");
        } else {
            perror("shutdown failed");
            goto cleanup;
        }
    }

    printf("Successfully performed half-close (SHUT_WR). We can still receive data.\n");

    // (Real application would now loop, reading data from the peer)

cleanup:
    // 3. Fully close the socket descriptor
    close(sockfd);
    return (ret == 0 || ret == -1 && errno == ENOTCONN) ? EXIT_SUCCESS : EXIT_FAILURE;
}
